// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import { SharedErrors } from "./SharedErrors.sol";

contract MultiOwnable {
    mapping(address => bool) public isOwner;
    uint256 public ownerCount;

    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);

    modifier onlyOwner() {
        if (!isOwner[msg.sender]) revert SharedErrors.Unauthorized();
        _;
    }

    constructor(address[] memory initialOwners) {
        if (initialOwners.length == 0) revert SharedErrors.InvalidInput();
        for (uint256 i = 0; i < initialOwners.length; i++) {
            address ownerAddr = initialOwners[i];
            if (ownerAddr == address(0)) revert SharedErrors.InvalidAddress();
            if (!isOwner[ownerAddr]) {
                isOwner[ownerAddr] = true;
                ownerCount++;
                emit OwnerAdded(ownerAddr);
            }
        }
    }

    function addOwner(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert SharedErrors.InvalidAddress();
        if (isOwner[newOwner]) revert SharedErrors.InvalidInput();
        isOwner[newOwner] = true;
        ownerCount++;
        emit OwnerAdded(newOwner);
    }

    function removeOwner(address ownerToRemove) external onlyOwner {
        if (!isOwner[ownerToRemove]) revert SharedErrors.InvalidInput();
        if (ownerCount <= 1) revert SharedErrors.InvalidInput();
        isOwner[ownerToRemove] = false;
        ownerCount--;
        emit OwnerRemoved(ownerToRemove);
    }

    function renounceOwnership() external onlyOwner {
        if (ownerCount <= 1) revert SharedErrors.InvalidInput();
        isOwner[msg.sender] = false;
        ownerCount--;
        emit OwnerRemoved(msg.sender);
    }
}

contracts/PointsManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { SharedErrors } from "./SharedErrors.sol";
import { SharedEvents } from "./SharedEvents.sol";
import { LevelMath } from "./libraries/LevelMath.sol";
import { IPointsManager } from "./interfaces/IPointsManager.sol";
import { MultiOwnable } from "./MultiOwnable.sol";

/// @title PointsManager
/// @notice On-chain verification layer for player profiles, XP, points, spins, and reward claims
/// @dev Backend-authorized only. Never allows self-editing.
contract PointsManager is AccessControl, IPointsManager, MultiOwnable {
    bytes32 public constant BACKEND_ROLE = keccak256("BACKEND_ROLE");

    /// @notice Mapping of player address to profile
    mapping(address => Profile) public profiles;
    /// @notice Mapping of request ID to processed status for replay protection
    mapping(bytes32 => bool) public processedRequestIds;

    /// @notice Aggregated player statistics
    PlayerStatistics public playerStats;

    /// @notice Address of the ActivityRegistry contract
    address public immutable activityRegistry;
    /// @notice Address of the SpinRewardManager contract
    address public immutable spinRewardManager;

    /// @notice Reverts if sender is not authorized backend
    modifier onlyBackend() {
        if (!hasRole(BACKEND_ROLE, msg.sender)) revert SharedErrors.Unauthorized();
        _;
    }

    /// @notice Reverts if amount is zero
    /// @param amount The amount to check
    modifier onlyNonZeroAmount(uint256 amount) {
        if (amount == 0) revert SharedErrors.InvalidAmount();
        _;
    }

    /// @notice Initializes the PointsManager with associated contracts
    /// @param _activityRegistry Address of the ActivityRegistry contract
    /// @param _spinRewardManager Address of the SpinRewardManager contract
    constructor(address _activityRegistry, address _spinRewardManager, address[] memory initialOwners) MultiOwnable(initialOwners) {
        activityRegistry = _activityRegistry;
        spinRewardManager = _spinRewardManager;

        for (uint256 i = 0; i < initialOwners.length; i++) {
            _grantRole(DEFAULT_ADMIN_ROLE, initialOwners[i]);
            _grantRole(BACKEND_ROLE, initialOwners[i]);
        }
    }

    /// @notice Grants XP to a player and auto-updates level
    /// @param player The player address
    /// @param amount The XP amount to grant
    /// @param requestId Unique request ID for replay protection
    function grantXP(address player, uint256 amount, bytes32 requestId)
        external
        onlyBackend
        onlyNonZeroAmount(amount)
    {
        if (processedRequestIds[requestId]) revert SharedErrors.DuplicateRequestId();
        processedRequestIds[requestId] = true;

        Profile storage playerProfile = profiles[player];
        uint256 oldLevel = playerProfile.level;

        unchecked {
            playerProfile.xp += amount;
            playerProfile.level = LevelMath.calculateLevel(playerProfile.xp);
            playerProfile.lifetimeXP += amount;
        }

        playerStats.totalXPGranted += amount;

        emit SharedEvents.XPGranted(player, amount, playerProfile.xp, requestId);

        if (playerProfile.level > oldLevel) {
            emit SharedEvents.LevelUp(player, playerProfile.level, playerProfile.xp);
        }

        emit SharedEvents.ProfileUpdated(player);
    }

    /// @notice Grants points to a player
    /// @param player The player address
    /// @param amount The points amount to grant
    /// @param requestId Unique request ID for replay protection
    function grantPoints(address player, uint256 amount, bytes32 requestId)
        external
        onlyBackend
        onlyNonZeroAmount(amount)
    {
        if (processedRequestIds[requestId]) revert SharedErrors.DuplicateRequestId();
        processedRequestIds[requestId] = true;

        Profile storage playerProfile = profiles[player];

        unchecked {
            playerProfile.points += amount;
            playerProfile.lifetimePoints += amount;
        }

        playerStats.totalPointsGranted += amount;

        emit SharedEvents.PointsGranted(player, amount, playerProfile.points, requestId);
        emit SharedEvents.ProfileUpdated(player);
    }

    /// @notice Deducts points from a player
    /// @param player The player address
    /// @param amount The points amount to deduct
    /// @param requestId Unique request ID for replay protection
    function deductPoints(address player, uint256 amount, bytes32 requestId)
        external
        onlyBackend
        onlyNonZeroAmount(amount)
    {
        if (processedRequestIds[requestId]) revert SharedErrors.DuplicateRequestId();
        processedRequestIds[requestId] = true;

        Profile storage playerProfile = profiles[player];
        if (playerProfile.points < amount) revert SharedErrors.InsufficientBalance();

        unchecked {
            playerProfile.points -= amount;
        }

        playerStats.totalPointsDeducted += amount;

        emit SharedEvents.PointsDeducted(player, amount, playerProfile.points, requestId);
        emit SharedEvents.ProfileUpdated(player);
    }

    /// @notice Grants spins to a player
    /// @param player The player address
    /// @param amount The spin amount to grant
    /// @param requestId Unique request ID for replay protection
    function grantSpin(address player, uint256 amount, bytes32 requestId)
        external
        onlyBackend
        onlyNonZeroAmount(amount)
    {
        if (processedRequestIds[requestId]) revert SharedErrors.DuplicateRequestId();
        processedRequestIds[requestId] = true;

        Profile storage playerProfile = profiles[player];

        unchecked {
            playerProfile.availableSpins += amount;
        }

        playerStats.totalSpinsGranted += amount;

        emit SharedEvents.SpinGranted(player, amount, playerProfile.availableSpins, requestId);
        emit SharedEvents.ProfileUpdated(player);
    }

    /// @notice Records a reward claim for a player
    /// @param player The player address
    /// @param requestId Unique request ID for replay protection
    function grantRewardClaim(address player, bytes32 requestId)
        external
        onlyBackend
    {
        if (processedRequestIds[requestId]) revert SharedErrors.DuplicateRequestId();
        processedRequestIds[requestId] = true;

        Profile storage playerProfile = profiles[player];

        unchecked {
            playerProfile.rewardClaims += 1;
        }

        playerStats.totalRewardClaims += 1;

        emit SharedEvents.RewardClaimed(player, 0, requestId);
        emit SharedEvents.ProfileUpdated(player);
    }

    /// @notice Returns a player's profile
    /// @param player The player address
    /// @return The player profile struct
    function profile(address player) external view returns (Profile memory) {
        return profiles[player];
    }

    /// @notice Returns aggregated player statistics
    /// @return The player statistics struct
    function playerStatistics() external view returns (PlayerStatistics memory) {
        return playerStats;
    }

    /// @notice Grants XP to multiple players in a batch
    /// @param players Array of player addresses
    /// @param amounts Array of XP amounts
    /// @param requestIds Array of unique request IDs
    function batchGrantXP(address[] calldata players, uint256[] calldata amounts, bytes32[] calldata requestIds)
        external
        onlyBackend
    {
        if (players.length != amounts.length || players.length != requestIds.length) {
            revert SharedErrors.InvalidInput();
        }

        for (uint256 i = 0; i < players.length; i++) {
            if (processedRequestIds[requestIds[i]]) continue;

            processedRequestIds[requestIds[i]] = true;

            Profile storage playerProfile = profiles[players[i]];
            uint256 oldLevel = playerProfile.level;

            unchecked {
                playerProfile.xp += amounts[i];
                playerProfile.level = LevelMath.calculateLevel(playerProfile.xp);
                playerProfile.lifetimeXP += amounts[i];
            }

            playerStats.totalXPGranted += amounts[i];

            emit SharedEvents.XPGranted(players[i], amounts[i], playerProfile.xp, requestIds[i]);

            if (playerProfile.level > oldLevel) {
                emit SharedEvents.LevelUp(players[i], playerProfile.level, playerProfile.xp);
            }
        }
    }

    /// @notice Grants points to multiple players in a batch
    /// @param players Array of player addresses
    /// @param amounts Array of point amounts
    /// @param requestIds Array of unique request IDs
    function batchGrantPoints(address[] calldata players, uint256[] calldata amounts, bytes32[] calldata requestIds)
        external
        onlyBackend
    {
        if (players.length != amounts.length || players.length != requestIds.length) {
            revert SharedErrors.InvalidInput();
        }

        for (uint256 i = 0; i < players.length; i++) {
            if (processedRequestIds[requestIds[i]]) continue;

            processedRequestIds[requestIds[i]] = true;

            Profile storage playerProfile = profiles[players[i]];

            unchecked {
                playerProfile.points += amounts[i];
                playerProfile.lifetimePoints += amounts[i];
            }

            playerStats.totalPointsGranted += amounts[i];

            emit SharedEvents.PointsGranted(players[i], amounts[i], playerProfile.points, requestIds[i]);
        }
    }
}

contracts/RewardTreasury.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import { Pausable } from "@openzeppelin/contracts/utils/Pausable.sol";
import { SafeERC20, IERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { SharedErrors } from "./SharedErrors.sol";
import { SharedEvents } from "./SharedEvents.sol";
import { TransferHelper } from "./libraries/TransferHelper.sol";
import { IRewardTreasury } from "./interfaces/IRewardTreasury.sol";
import { MultiOwnable } from "./MultiOwnable.sol";

/// @title RewardTreasury
/// @notice Central vault for all Vibepool reward funds. Supports CELO and ERC20 assets.
/// @dev Follows Checks-Effects-Interactions pattern with ReentrancyGuard and Pausable.
contract RewardTreasury is IRewardTreasury, AccessControl, ReentrancyGuard, Pausable, MultiOwnable {
    using SafeERC20 for IERC20;

    bytes32 public constant TREASURY_MANAGER_ROLE = keccak256("TREASURY_MANAGER_ROLE");
    bytes32 public constant REWARD_MANAGER_ROLE = keccak256("REWARD_MANAGER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    /// @notice Mapping of asset address to asset info
    mapping(address => AssetInfo) public assets;
    /// @notice Ordered list of supported asset addresses
    address[] public supportedAssetList;
    /// @notice Mapping of asset address to per-asset statistics
    mapping(address => AssetStatistics) public assetStats;
    /// @notice Mapping of request ID to processed status for replay protection
    mapping(bytes32 => bool) private processedRequestIds;

    /// @notice Overall treasury statistics
    TreasuryStatistics public treasuryStats;

    /// @notice Native asset address (CELO)
    address public immutable nativeAsset;

    /// @notice Reverts if amount is zero
    modifier onlyNonZeroAmount(uint256 amount) {
        if (amount == 0) revert SharedErrors.InvalidAmount();
        _;
    }

    /// @notice Reverts if asset is not supported
    modifier onlySupportedAsset(address asset) {
        if (!_isSupportedAsset(asset)) revert SharedErrors.UnsupportedAsset();
        _;
    }

    /// @notice Reverts if asset is not enabled
    modifier onlyEnabledAsset(address asset) {
        if (!assets[asset].enabled) revert SharedErrors.AssetDisabled();
        _;
    }

    /// @notice Initializes the treasury with CELO as the default supported asset
    /// @param _nativeAsset The native asset address (CELO, typically address(0))
    constructor(address _nativeAsset, address[] memory initialOwners) MultiOwnable(initialOwners) {
        nativeAsset = _nativeAsset;

        for (uint256 i = 0; i < initialOwners.length; i++) {
            _grantRole(DEFAULT_ADMIN_ROLE, initialOwners[i]);
            _grantRole(TREASURY_MANAGER_ROLE, initialOwners[i]);
            _grantRole(REWARD_MANAGER_ROLE, initialOwners[i]);
            _grantRole(PAUSER_ROLE, initialOwners[i]);
        }

        assets[nativeAsset] = AssetInfo({
            assetAddress: nativeAsset,
            symbol: "CELO",
            decimals: 18,
            enabled: true
        });
        supportedAssetList.push(nativeAsset);
    }

    /// @notice Deposits native asset (CELO) into the treasury
    function deposit() external payable whenNotPaused onlyNonZeroAmount(msg.value) onlyEnabledAsset(nativeAsset) {
        _depositNative(msg.value);
    }

    /// @notice Deposits ERC20 asset into the treasury
    function depositERC20(address asset, uint256 amount)
        external
        whenNotPaused
        onlyNonZeroAmount(amount)
        onlySupportedAsset(asset)
        onlyEnabledAsset(asset)
        nonReentrant
    {
        IERC20(asset).safeTransferFrom(msg.sender, address(this), amount);

        AssetStatistics storage stats = assetStats[asset];
        stats.totalDeposited += amount;
        stats.balance += amount;

        treasuryStats.totalDeposits += amount;

        emit SharedEvents.TreasuryDeposit(asset, amount, uint64(block.timestamp));
    }

    /// @notice Withdraws assets from the treasury
    function withdraw(address asset, address to, uint256 amount)
        external
        whenNotPaused
        nonReentrant
        onlyRole(TREASURY_MANAGER_ROLE)
        onlySupportedAsset(asset)
        onlyNonZeroAmount(amount)
    {
        if (to == address(0)) revert SharedErrors.InvalidAddress();

        AssetStatistics storage stats = assetStats[asset];
        if (stats.balance < amount) revert SharedErrors.InsufficientBalance();

        stats.balance -= amount;

        treasuryStats.totalWithdrawals += amount;

        if (asset == nativeAsset) {
            TransferHelper.transferNative(to, amount);
        } else {
            IERC20(asset).safeTransfer(to, amount);
        }

        emit SharedEvents.TreasuryWithdrawal(asset, amount, to, uint64(block.timestamp));
    }

    /// @notice Executes a reward payout to a recipient
    function payout(address recipient, address asset, uint256 amount, bytes32 requestId)
        external
        whenNotPaused
        nonReentrant
        onlyRole(REWARD_MANAGER_ROLE)
        onlySupportedAsset(asset)
        onlyEnabledAsset(asset)
        onlyNonZeroAmount(amount)
    {
        if (recipient == address(0)) revert SharedErrors.InvalidAddress();
        if (processedRequestIds[requestId]) revert SharedErrors.DuplicateRequestId();

        processedRequestIds[requestId] = true;

        AssetStatistics storage stats = assetStats[asset];
        if (stats.balance < amount) revert SharedErrors.InsufficientBalance();

        stats.balance -= amount;
        stats.totalPaid += amount;

        treasuryStats.totalRewards += amount;
        treasuryStats.rewardCount += 1;
        if (amount > treasuryStats.largestReward) {
            treasuryStats.largestReward = amount;
        }

        if (asset == nativeAsset) {
            TransferHelper.transferNative(recipient, amount);
        } else {
            IERC20(asset).safeTransfer(recipient, amount);
        }

        emit SharedEvents.RewardPaid(recipient, asset, amount, requestId, uint64(block.timestamp));
    }

    /// @notice Returns the total native asset balance held by the treasury
    function treasuryBalance() external view returns (uint256) {
        return assetStats[nativeAsset].balance;
    }

    /// @notice Returns the balance of a specific asset held by the treasury
    function assetBalance(address asset) external view returns (uint256) {
        if (!_isSupportedAsset(asset)) revert SharedErrors.UnsupportedAsset();
        return assetStats[asset].balance;
    }

    /// @notice Checks if an asset is supported
    function isSupportedAsset(address asset) external view returns (bool) {
        return _isSupportedAsset(asset);
    }

    /// @notice Returns all supported assets
    function getSupportedAssets() external view returns (AssetInfo[] memory) {
        AssetInfo[] memory result = new AssetInfo[](supportedAssetList.length);
        for (uint256 i = 0; i < supportedAssetList.length; i++) {
            result[i] = assets[supportedAssetList[i]];
        }
        return result;
    }

    /// @notice Enables a new asset for deposits and payouts
    function enableAsset(address asset, string calldata symbol, uint8 decimals) external onlyOwner {
        if (asset == address(0)) revert SharedErrors.InvalidAddress();
        if (assets[asset].assetAddress != address(0)) revert SharedErrors.AssetAlreadyExists();

        assets[asset] = AssetInfo({
            assetAddress: asset,
            symbol: symbol,
            decimals: decimals,
            enabled: true
        });
        supportedAssetList.push(asset);

        emit SharedEvents.AssetEnabled(asset, symbol);
    }

    /// @notice Disables an asset
    function disableAsset(address asset) external onlyOwner {
        if (assets[asset].assetAddress == address(0)) revert SharedErrors.AssetNotFound();

        assets[asset].enabled = false;
        emit SharedEvents.AssetDisabled(asset, assets[asset].symbol);
    }

    /// @notice Returns statistics for a specific asset
    function assetStatistics(address asset) external view returns (AssetStatistics memory) {
        if (!_isSupportedAsset(asset)) revert SharedErrors.UnsupportedAsset();
        return assetStats[asset];
    }

    /// @notice Returns overall treasury statistics
    function treasuryStatistics() external view returns (TreasuryStatistics memory) {
        return treasuryStats;
    }

    /// @notice Pauses all state-changing operations
    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
        emit SharedEvents.Paused();
    }

    /// @notice Unpauses all state-changing operations
    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
        emit SharedEvents.Unpaused();
    }

    /// @notice Internal check for supported asset
    function _isSupportedAsset(address asset) internal view returns (bool) {
        return asset == nativeAsset || assets[asset].assetAddress != address(0);
    }

    /// @notice Accepts native asset deposits
    receive() external payable whenNotPaused {
        if (msg.value == 0) revert SharedErrors.InvalidAmount();
        _depositNative(msg.value);
    }

    function _depositNative(uint256 amount) private {
        address asset = nativeAsset;
        AssetStatistics storage stats = assetStats[asset];
        stats.totalDeposited += amount;
        stats.balance += amount;
        treasuryStats.totalDeposits += amount;
        emit SharedEvents.TreasuryDeposit(asset, amount, uint64(block.timestamp));
    }
}

