    event Paused();
    event Unpaused();
}

contracts/SpinEconomy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import { Pausable } from "@openzeppelin/contracts/utils/Pausable.sol";
import { SafeERC20, IERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC20Permit } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import { SharedErrors } from "./SharedErrors.sol";
import { ISpinEconomy } from "./interfaces/ISpinEconomy.sol";
import { IRewardTreasury } from "./interfaces/IRewardTreasury.sol";
import { IPointsManager } from "./interfaces/IPointsManager.sol";
import { MultiOwnable } from "./MultiOwnable.sol";

/// @title SpinEconomy
/// @notice Contract-only entry fees and item purchases; forwards 100% to treasury.
/// @dev ERC20 users can call *WithPermit (OpenZeppelin IERC20Permit / EIP-2612) for a single tx.
contract SpinEconomy is ISpinEconomy, AccessControl, ReentrancyGuard, Pausable, MultiOwnable {
    using SafeERC20 for IERC20;

    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    address public immutable nativeAsset;
    address public treasury;
    address public prizeVault;
    uint16 public treasuryBps; // preserved for interface compatibility, set to 10_000 internally

    address public pointsManager;
    uint256 public pointsReward; // Amount of XP & Points awarded per item purchase

    mapping(address => bool) public assetEnabled;
    mapping(address => uint8) public assetDecimals;
    address[] public assetList;

    modifier onlyEnabledAsset(address asset) {
        if (!assetEnabled[asset]) revert SharedErrors.AssetDisabled();
        _;
    }

    constructor(
        address _nativeAsset,
        address _treasury,
        address _prizeVault,
        uint16 _treasuryBps,
        address _pointsManager,
        address[] memory initialOwners
    ) MultiOwnable(initialOwners) {
        if (_treasury == address(0) || _prizeVault == address(0)) revert SharedErrors.InvalidAddress();
        if (_treasuryBps > 10_000) revert SharedErrors.InvalidInput();

        nativeAsset = _nativeAsset;
        treasury = _treasury;
        prizeVault = _prizeVault;
        treasuryBps = 10_000; // Force 100% to treasury
        pointsManager = _pointsManager;

        for (uint256 i = 0; i < initialOwners.length; i++) {
            _grantRole(DEFAULT_ADMIN_ROLE, initialOwners[i]);
            _grantRole(PAUSER_ROLE, initialOwners[i]);
        }

        assetEnabled[_nativeAsset] = true;
        assetDecimals[_nativeAsset] = 18;
        assetList.push(_nativeAsset);
    }

    function enableAsset(address asset, uint8 decimals_) external onlyOwner {
        if (asset == address(0)) revert SharedErrors.InvalidAddress();
        if (assetEnabled[asset]) revert SharedErrors.AssetAlreadyExists();
        assetEnabled[asset] = true;
        assetDecimals[asset] = decimals_;
        assetList.push(asset);
    }

    function setTreasuryBps(uint16 bps) external onlyOwner {
        if (bps > 10_000) revert SharedErrors.InvalidInput();
        treasuryBps = bps;
        emit SplitUpdated(bps);
    }

    function setTreasury(address t) external onlyOwner {
        if (t == address(0)) revert SharedErrors.InvalidAddress();
        treasury = t;
        emit TreasuryUpdated(t);
    }

    function setPrizeVault(address v) external onlyOwner {
        if (v == address(0)) revert SharedErrors.InvalidAddress();
        prizeVault = v;
        emit VaultUpdated(v);
    }

    function setPointsReward(uint256 _pointsReward) external onlyOwner {
        pointsReward = _pointsReward;
    }

    function setPointsManager(address _pointsManager) external onlyOwner {
        pointsManager = _pointsManager;
    }

    function payEntry(address asset, uint256 amount, bytes32 sessionRef)
        external
        payable
        whenNotPaused
        nonReentrant
        onlyEnabledAsset(asset)
    {
        amount = _intake(asset, amount);
        _forward(asset, amount, 0);
        emit EntryPaid(msg.sender, asset, amount, amount, 0, sessionRef);
    }

    function purchaseItem(bytes32 itemId, address asset, uint256 amount)
        external
        payable
        whenNotPaused
        nonReentrant
        onlyEnabledAsset(asset)
    {
        if (itemId == bytes32(0)) revert SharedErrors.InvalidInput();
        amount = _intake(asset, amount);
        _forward(asset, amount, 0);

        if (pointsManager != address(0) && pointsReward > 0) {
            bytes32 xpReq = keccak256(abi.encodePacked(msg.sender, itemId, block.timestamp, "XP"));
            bytes32 ptsReq = keccak256(abi.encodePacked(msg.sender, itemId, block.timestamp, "PTS"));
            IPointsManager(pointsManager).grantXP(msg.sender, pointsReward, xpReq);
            IPointsManager(pointsManager).grantPoints(msg.sender, pointsReward, ptsReq);
        }

        emit ItemPurchased(msg.sender, itemId, asset, amount, amount, 0);
    }

    /// @inheritdoc ISpinEconomy
    function payEntryWithPermit(
        address asset,
        uint256 amount,
        bytes32 sessionRef,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external whenNotPaused nonReentrant onlyEnabledAsset(asset) {
        if (asset == nativeAsset) revert SharedErrors.InvalidInput();
        if (amount == 0) revert SharedErrors.InvalidAmount();
        _permit(asset, amount, deadline, v, r, s);
        amount = _intake(asset, amount);
        _forward(asset, amount, 0);
        emit EntryPaid(msg.sender, asset, amount, amount, 0, sessionRef);
    }

    /// @inheritdoc ISpinEconomy
    function purchaseItemWithPermit(
        bytes32 itemId,
        address asset,
        uint256 amount,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external whenNotPaused nonReentrant onlyEnabledAsset(asset) {
        if (itemId == bytes32(0)) revert SharedErrors.InvalidInput();
        if (asset == nativeAsset) revert SharedErrors.InvalidInput();
        if (amount == 0) revert SharedErrors.InvalidAmount();
        _permit(asset, amount, deadline, v, r, s);
        amount = _intake(asset, amount);
        _forward(asset, amount, 0);

        if (pointsManager != address(0) && pointsReward > 0) {
            bytes32 xpReq = keccak256(abi.encodePacked(msg.sender, itemId, block.timestamp, "XP"));
            bytes32 ptsReq = keccak256(abi.encodePacked(msg.sender, itemId, block.timestamp, "PTS"));
            IPointsManager(pointsManager).grantXP(msg.sender, pointsReward, xpReq);
            IPointsManager(pointsManager).grantPoints(msg.sender, pointsReward, ptsReq);
        }

        emit ItemPurchased(msg.sender, itemId, asset, amount, amount, 0);
    }

    function _permit(address asset, uint256 amount, uint256 deadline, uint8 v, bytes32 r, bytes32 s) private {
        IERC20Permit(asset).permit(msg.sender, address(this), amount, deadline, v, r, s);
    }

    function _intake(address asset, uint256 amount) private returns (uint256) {
        if (asset == nativeAsset) {
            if (msg.value == 0) revert SharedErrors.InvalidAmount();
            return msg.value;
        }
        if (amount == 0) revert SharedErrors.InvalidAmount();
        if (msg.value != 0) revert SharedErrors.InvalidInput();
        IERC20(asset).safeTransferFrom(msg.sender, address(this), amount);
        return amount;
    }

    function _forward(address asset, uint256 toTreasury, uint256 toVault) private {
        if (asset == nativeAsset) {
            if (toTreasury > 0) {
                IRewardTreasury(treasury).deposit{ value: toTreasury }();
            }
            if (toVault > 0) {
                (bool ok,) = prizeVault.call{ value: toVault }("");
                if (!ok) revert SharedErrors.TransferFailed();
            }
        } else {
            if (toTreasury > 0) {
                IERC20(asset).forceApprove(treasury, toTreasury);
                IRewardTreasury(treasury).depositERC20(asset, toTreasury);
            }
            if (toVault > 0) {
                IERC20(asset).safeTransfer(prizeVault, toVault);
            }
        }
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }
}

contracts/SpinPrizeVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import { Pausable } from "@openzeppelin/contracts/utils/Pausable.sol";
import { SafeERC20, IERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { SharedErrors } from "./SharedErrors.sol";
import { TransferHelper } from "./libraries/TransferHelper.sol";
import { ISpinPrizeVault } from "./interfaces/ISpinPrizeVault.sol";
import { MultiOwnable } from "./MultiOwnable.sol";

/// @title SpinPrizeVault
/// @notice Holds Spin Hunt prize liquidity; DB_MANAGER credits claimable balances; users withdraw when liquid.
contract SpinPrizeVault is ISpinPrizeVault, AccessControl, ReentrancyGuard, Pausable, MultiOwnable {
    using SafeERC20 for IERC20;

    bytes32 public constant DB_MANAGER_ROLE = keccak256("DB_MANAGER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    address public immutable nativeAsset;

    mapping(address => bool) public assetEnabled;
    mapping(address => uint8) public assetDecimals;
    mapping(address => string) public assetSymbol;
    address[] public assetList;

    /// @notice User claimable balances per asset (accounting)
    mapping(address => mapping(address => uint256)) private _claimable;

    /// @notice Liquidity reserved for claimable credits (must stay <= actual holdings)
    mapping(address => uint256) public reserved;

    mapping(bytes32 => bool) private processedRequestIds;

    modifier onlyEnabledAsset(address asset) {
        if (!assetEnabled[asset]) revert SharedErrors.AssetDisabled();
        _;
    }

    constructor(address _nativeAsset, address[] memory initialOwners) MultiOwnable(initialOwners) {
        nativeAsset = _nativeAsset;

        for (uint256 i = 0; i < initialOwners.length; i++) {
            _grantRole(DEFAULT_ADMIN_ROLE, initialOwners[i]);
            _grantRole(DB_MANAGER_ROLE, initialOwners[i]);
            _grantRole(PAUSER_ROLE, initialOwners[i]);
        }

        assetEnabled[_nativeAsset] = true;
        assetDecimals[_nativeAsset] = 18;
        assetSymbol[_nativeAsset] = "CELO";
        assetList.push(_nativeAsset);
    }

    function enableAsset(address asset, string calldata symbol, uint8 decimals_)
        external
        onlyOwner
    {
        if (asset == address(0)) revert SharedErrors.InvalidAddress();
        if (assetEnabled[asset]) revert SharedErrors.AssetAlreadyExists();
        assetEnabled[asset] = true;
        assetDecimals[asset] = decimals_;
        assetSymbol[asset] = symbol;
        assetList.push(asset);
    }

    function disableAsset(address asset) external onlyOwner {
        if (!assetEnabled[asset]) revert SharedErrors.AssetNotFound();
        if (asset == nativeAsset) revert SharedErrors.InvalidInput();
        assetEnabled[asset] = false;
    }

    /// @notice Anyone can fund prize liquidity
    function fund(address asset, uint256 amount)
        external
        payable
        whenNotPaused
        nonReentrant
        onlyEnabledAsset(asset)
    {
        if (asset == nativeAsset) {
            if (msg.value == 0) revert SharedErrors.InvalidAmount();
            amount = msg.value;
        } else {
            if (amount == 0) revert SharedErrors.InvalidAmount();
            if (msg.value != 0) revert SharedErrors.InvalidInput();
            IERC20(asset).safeTransferFrom(msg.sender, address(this), amount);
        }
        emit VaultFunded(asset, amount, msg.sender);
    }

    receive() external payable whenNotPaused {
        if (msg.value == 0) revert SharedErrors.InvalidAmount();
        if (!assetEnabled[nativeAsset]) revert SharedErrors.AssetDisabled();
        emit VaultFunded(nativeAsset, msg.value, msg.sender);
    }

    /// @notice Credit user claimable reward (DB_MANAGER). Does not transfer tokens.
    function creditReward(address user, address asset, uint256 amount, bytes32 requestId)
        external
        whenNotPaused
        nonReentrant
        onlyRole(DB_MANAGER_ROLE)
        onlyEnabledAsset(asset)
    {
        if (user == address(0)) revert SharedErrors.InvalidAddress();
        if (amount == 0) revert SharedErrors.InvalidAmount();
        if (processedRequestIds[requestId]) revert SharedErrors.DuplicateRequestId();

        uint256 liquid = liquidBalance(asset);
        if (liquid < amount) revert SharedErrors.InsufficientBalance();

        processedRequestIds[requestId] = true;
        _claimable[user][asset] += amount;
        reserved[asset] += amount;

        emit RewardCredited(user, asset, amount, requestId);
    }

    /// @notice User withdraws claimable amount when vault has liquidity
    function withdraw(address asset, uint256 amount)
        external
        whenNotPaused
        nonReentrant
        onlyEnabledAsset(asset)
    {
        if (amount == 0) revert SharedErrors.InvalidAmount();
        uint256 owed = _claimable[msg.sender][asset];
        if (owed < amount) revert SharedErrors.InsufficientBalance();
        if (liquidBalance(asset) < amount) revert SharedErrors.InsufficientBalance();

        _claimable[msg.sender][asset] = owed - amount;
        reserved[asset] -= amount;

        if (asset == nativeAsset) {
            TransferHelper.transferNative(msg.sender, amount);
        } else {
            IERC20(asset).safeTransfer(msg.sender, amount);
        }

        emit RewardWithdrawn(msg.sender, asset, amount, bytes32(0));
    }

    function claimable(address user, address asset) external view returns (uint256) {
        return _claimable[user][asset];
    }

    /// @notice Unreserved holdings available to back new credits / withdrawals
    function liquidBalance(address asset) public view returns (uint256) {
        uint256 held = asset == nativeAsset ? address(this).balance : IERC20(asset).balanceOf(address(this));
        uint256 res = reserved[asset];
        return held > res ? held - res : 0;
    }

    function canWithdraw(address user, address asset, uint256 amount) external view returns (bool) {
        if (amount == 0) return false;
        if (_claimable[user][asset] < amount) return false;
        // For withdraw, liquid must cover amount; reserved includes this user's claimable
        uint256 held = asset == nativeAsset ? address(this).balance : IERC20(asset).balanceOf(address(this));
        return held >= amount;
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }
}

contracts/SpinRewardManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import { AccessControl } from "@openzeppelin/contracts/access/AccessControl.sol";
import { SharedErrors } from "./SharedErrors.sol";
import { SharedEvents } from "./SharedEvents.sol";
import { ISpinRewardManager } from "./interfaces/ISpinRewardManager.sol";
import { MultiOwnable } from "./MultiOwnable.sol";

/// @title SpinRewardManager
/// @notice On-chain accounting for spin tickets and rewards
/// @dev Backend-authorized only. Wheel logic remains off-chain.
contract SpinRewardManager is AccessControl, ISpinRewardManager, MultiOwnable {
    bytes32 public constant BACKEND_ROLE = keccak256("BACKEND_ROLE");

    /// @notice Mapping of player address to spin profile
    mapping(address => SpinProfile) public spinProfiles;
    /// @notice Mapping of request ID to processed status for replay protection
    mapping(bytes32 => bool) public processedRequestIds;

    /// @notice Aggregated spin statistics
    SpinStatistics public spinStats;

    /// @notice Reverts if sender is not authorized backend
    modifier onlyBackend() {
        if (!hasRole(BACKEND_ROLE, msg.sender)) revert SharedErrors.Unauthorized();
        _;
    }

    /// @notice Initializes the SpinRewardManager
    constructor(address[] memory initialOwners) MultiOwnable(initialOwners) {
        for (uint256 i = 0; i < initialOwners.length; i++) {
            _grantRole(DEFAULT_ADMIN_ROLE, initialOwners[i]);
            _grantRole(BACKEND_ROLE, initialOwners[i]);
        }
    }

    /// @notice Grants spin tickets to a player
    /// @param player The player address
    /// @param amount The number of spins to grant
    /// @param requestId Unique request ID for replay protection
    function grantSpin(address player, uint256 amount, bytes32 requestId)
        external
        onlyBackend
    {
        if (amount == 0) revert SharedErrors.InvalidAmount();
        if (processedRequestIds[requestId]) revert SharedErrors.DuplicateRequestId();

        processedRequestIds[requestId] = true;

        SpinProfile storage spinProfile = spinProfiles[player];

        unchecked {
            spinProfile.availableSpins += uint64(amount);
            spinProfile.lifetimeSpinsEarned += uint64(amount);
        }

        spinStats.totalSpinsGranted += amount;

        emit SharedEvents.SpinGranted(player, amount, spinProfile.availableSpins, requestId);
    }

    /// @notice Consumes one spin ticket from a player
    /// @param player The player address
    /// @param requestId Unique request ID for replay protection
    function consumeSpin(address player, bytes32 requestId)
        external
        onlyBackend
    {
        if (processedRequestIds[requestId]) revert SharedErrors.DuplicateRequestId();

        SpinProfile storage spinProfile = spinProfiles[player];
        if (spinProfile.availableSpins == 0) revert SharedErrors.NoSpinRemaining();

        processedRequestIds[requestId] = true;

        unchecked {
            spinProfile.availableSpins -= 1;
            spinProfile.lifetimeSpinsUsed += 1;
        }

        spinStats.totalSpinsConsumed += 1;

        emit SharedEvents.SpinConsumed(player, spinProfile.availableSpins, requestId);
    }

    /// @notice Records a reward won from a spin
    /// @param player The player address
    /// @param amount The reward amount
    /// @param requestId Unique request ID for replay protection
    function recordReward(address player, uint256 amount, bytes32 requestId)
        external
        onlyBackend
    {
        if (amount == 0) revert SharedErrors.InvalidAmount();
        if (processedRequestIds[requestId]) revert SharedErrors.DuplicateRequestId();

        processedRequestIds[requestId] = true;

        SpinProfile storage spinProfile = spinProfiles[player];

        unchecked {
            spinProfile.lifetimeRewards += amount;
        }

        spinStats.totalRewardsRecorded += amount;

        emit SharedEvents.RewardRecorded(player, amount, requestId);
    }

    /// @notice Returns a player's spin profile
    /// @param player The player address
    /// @return The spin profile struct
    function profile(address player) external view returns (SpinProfile memory) {
        return spinProfiles[player];
    }

    /// @notice Returns aggregated spin statistics
    /// @return The spin statistics struct
    function spinStatistics() external view returns (SpinStatistics memory) {
        return spinStats;
    }
}
